/bin/zsh -lc "sed -n '1,240p' money.v1.py && shasum -a 256 money.v1.py && python3 - <<'PY'
from decimal import Decimal
import importlib.util
spec=importlib.util.spec_from_file_location('money','money.v1.py')
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
cases=[
 (Decimal('10.00'),3),
 (Decimal('-10.00'),3),
 (Decimal('0.01'),3),
 (Decimal('-0.01'),3),
 (Decimal('1.00'),7),
 (Decimal('-1.00'),7),
 (Decimal('0'),1),
]
for total, ways in cases:
 try:
  r=m.split_evenly(total,ways)
  print(repr(total),ways,'=>',r,'len',len(r),'sum',sum(r,Decimal(0)), 'types',[type(x).__name__ for x in r])
 except Exception as e: print(repr(total),ways,'EXC',type(e).__name__,str(e))
for ways in [0,-1]:
 try: print('invalid',ways,m.split_evenly(Decimal('1.00'),ways))
 except Exception as e: print('invalid',ways,'EXC',type(e).__name__,str(e))
PY"

